parameters.content:
import { cookies, headers } from 'next/headers';

export default async function UserPreferences() {
  const cookieStore = await cookies();
  const theme = cookieStore.get('theme')?.value || 'light';

  const headersList = await headers();
  const language = headersList.get('accept-language') || 'en-US'; // Default fallback

  return (
    <div className="p-4 border rounded shadow-sm bg-gray-50 dark:bg-gray-800">
      <h2 className="text-xl font-bold mb-2">User Settings</h2>
      <p>
        <strong>Theme:</strong> {theme}
      </p>
      <p>
        <strong>Preferred Language:</strong> {language}
      </p>
    </div>
  );
}

